    ...(typeof LanguageModel === 'undefined' ? {} : { prompt: LanguageModel }),
    ...(typeof Rewriter === 'undefined' ? {} : { rewriter: Rewriter }),
    ...(typeof Proofreader === 'undefined' ? {} : { proofreader: Proofreader }),
