export type ErrorCode =
  | 'INVALID_MESSAGE'
  | 'BUSY'
  | 'UNKNOWN_REQUEST'
  | 'UNAVAILABLE'
  | 'DISCONNECTED'
  | 'TIMEOUT'
  | 'WEBGPU_UNAVAILABLE'
  | 'INSUFFICIENT_RESOURCES'
  | 'MODEL_DOWNLOAD'
  | 'DOWNLOAD_REQUIRED'
  | 'CONTEXT_LIMIT'
  | 'NATIVE_QUOTA'
  | 'NATIVE_NOT_SUPPORTED'
  | 'EMPTY_OUTPUT'
  | 'TRUNCATED_OUTPUT'
  | 'INVALID_OUTPUT'
  | 'PRESERVATION_RISK'
  | 'SEMANTIC_RISK'
  | 'SEMANTIC_INVALID';
