      'UNKNOWN_REQUEST',
      'UNAVAILABLE',
      'DISCONNECTED',
      'TIMEOUT',
      'WEBGPU_UNAVAILABLE',
      'INSUFFICIENT_RESOURCES',
      'MODEL_DOWNLOAD',
      'DOWNLOAD_REQUIRED',
      'CONTEXT_LIMIT',
      'EMPTY_OUTPUT',
      'TRUNCATED_OUTPUT',
      'INVALID_OUTPUT',
      'PRESERVATION_RISK',
      'SEMANTIC_RISK',
      'SEMANTIC_INVALID',
