          'preparing',
          'downloading',
          'loading',
          'ready',
          'generating',
          'validating',
          'reviewing',
        ].includes(String(value.phase)) &&
        typeof value.percent === 'number' &&
        Number.isFinite(value.percent) &&
        value.percent >= 0 &&
        value.percent <= 100 &&
        (value.variant === null || isLocalVariant(value.variant))
