import type { ComparisonOptions } from '../benchmark/comparison-run';
self.onmessage = (event: MessageEvent<ComparisonOptions>) => {
  self.onmessage = null;
  const engine = event.data.candidate === 'gemma' ? new GemmaEngine() : new WebLLMEngine();
  void comparisonRun(
    engine,
    event.data,
      (value) => {
      self.postMessage(value);
        return Promise.resolve();
    },
    () =>
      new Promise<void>((resolve) => {
        self.onmessage = () => {
          self.onmessage = null;
          resolve();
        };
      }),
  ).then(
    () => self.postMessage({ type: 'done' }),
    (error: unknown) => self.postMessage({ type: 'fatal', error: String(error) }),
  );
};

